150	#[async_trait]
151	impl AppRuntime for DefaultAppRuntime {
152	    async fn start_app(
153	        &self,
154	        app_name: &str,
155	        params: Option<serde_json::Value>,
156	        auto_answer: bool,
157	    ) -> AppResult<()> {
158	        // Check if already running
159	        {
160	            let running = self.running.read().await;
161	            if running.is_some() {
162	                return Err(AppRuntimeError::AlreadyRunning(app_name.to_string()));
163	            }
164	        }
165	
166	        // Create event channel
167	        let (_event_tx, event_rx) = mpsc::unbounded_channel();
168	        let (_fired_timer_tx, fired_timer_rx) = mpsc::unbounded_channel();
169	
170	        // Create controller
171	        let (controller, _timer_rx) = CallController::new(self.handle.clone(), event_rx);
172	        let _ = _timer_rx; // We use fired_timer_rx instead
173	
174	        // Create cancel token
175	        let cancel_token = CancellationToken::new();
176	
177	        // Get the app from factory
178	        let app = if let Some(factory) = &self.app_factory {
179	            factory.create_app(app_name, params.clone(), &self.context)
180	        } else {
181	            None
182	        };
183	
184	        let app = match app {
185	            Some(app) => app,
186	            None => return Err(AppRuntimeError::UnknownApp(app_name.to_string())),
187	        };
188	
189	        // Store running state
190	        {
191	            let mut running = self.running.write().await;
192	            *running = Some(RunningApp {
193	                name: app_name.to_string(),
194	                cancel_token: cancel_token.clone(),
195	            });
196	        }
197	
198	        // Auto-answer if requested
199	        if auto_answer {
200	            self.handle
201	                .send_command(SessionAction::AcceptCall {
202	                    callee: None,
203	                    sdp: None,
204	                    dialog_id: None,
205	                })
206	                .map_err(|e| AppRuntimeError::StartFailed(e.to_string()))?;
207	        }
208	
209	        // Spawn the event loop
210	        let session_id_for_log = self.session_id.clone();
211	        let app_name_owned = app_name.to_string();
212	        let context = self.context.clone();
213	
214	        tokio::spawn(async move {
215	            let event_loop = crate::call::app::AppEventLoop::new(
216	                app,
217	                controller,
218	                (*context).clone(),
219	                cancel_token,
220	                fired_timer_rx,
221	            );
222	
223	            if let Err(e) = event_loop.run().await {
224	                tracing::error!("App {} failed for session {}: {}", app_name_owned, session_id_for_log, e);
225	            }
226	
227	            // Clean up event sender when app exits
228	            // Note: This cleanup should ideally be done through the handle
229	            tracing::info!("App {} exited for session {}", app_name_owned, session_id_for_log);
230	        });
231	
232	        tracing::info!("App {} started for session {}", app_name, self.session_id);
233	        Ok(())
234	    }
235	
236	    async fn stop_app(&self, reason: Option<String>) -> AppResult<()> {
237	        let running = {
238	            let running = self.running.read().await;
239	            running.clone()
240	        };
241	
242	        match running {
243	            Some(running) => {
244	                // Cancel the event loop
245	                running.cancel_token.cancel();
246	
247	                // Clear running state
248	                {
249	                    let mut running_guard = self.running.write().await;
250	                    *running_guard = None;
251	                }
252	
253	                tracing::info!(
254	                    "App {} stopped for session {}: {}",
255	                    running.name,
256	                    self.session_id,
257	                    reason.unwrap_or_else(|| "no reason".to_string())
258	                );
259	
260	                Ok(())
261	            }
262	            None => Err(AppRuntimeError::NotRunning),
263	        }
264	    }
265	
266	    fn inject_event(&self, event: serde_json::Value) -> AppResult<()> {
267	        // Parse the event type and convert to ControllerEvent
268	        let controller_event = parse_json_event(&event)?;
269	
270	        // Try to send via the handle's send_app_event
271	        if self.handle.send_app_event(controller_event) {
272	            Ok(())
273	        } else {
274	            Err(AppRuntimeError::InjectFailed(
275	                "no app running or channel closed".to_string(),
276	            ))
277	        }
278	    }
279	
280	    fn is_running(&self) -> bool {
281	        // Check if there's an app event sender set
282	        // This is a quick synchronous check
283	        if let Ok(guard) = self.running.try_read() {
284	            guard.is_some()
285	        } else {
286	            false
287	        }
288	    }
289	
290	    fn status(&self) -> AppStatus {
291	        if self.is_running() {
292	            AppStatus::Running
293	        } else {
294	            AppStatus::Idle
295	        }
296	    }
297	
298	    fn current_app(&self) -> Option<String> {
299	        if let Ok(guard) = self.running.try_read() {
300	            guard.as_ref().map(|r| r.name.clone())
301	        } else {
302	            None
303	        }
304	    }
305	
306	    fn required_capabilities(&self) -> Vec<MediaCapability> {
307	        if let Ok(guard) = self.running.try_read() {
308	            if let Some(running) = guard.as_ref() {
309	                let descriptor = self.get_descriptor(&running.name);
310	                return descriptor.required_capabilities;
311	            }
312	        }
313	        vec![]
314	    }
315	
316	    fn app_descriptor(&self, app_name: &str) -> Option<AppDescriptor> {
317	        Some(self.get_descriptor(app_name))
318	    }
319	}
