 44	fn q850_cause_from_status(code: &rsip::StatusCode) -> u16 {
 45	    match u16::from(code.clone()) {
 46	        400 | 401 | 402 | 403 | 405 | 406 | 407 | 421 | 603 => 21, // call rejected / not allowed
 47	        404 | 484 | 604 => 1,                                      // unallocated number
 48	        410 => 22,                                                 // number changed
 49	        413 | 414 | 416 | 420 => 127, // interworking / feature not supported
 50	        480 | 408 => 18,              // no user responding / timeout
 51	        486 | 600 => 17,              // user busy
 52	        487 => 31,                    // request terminated / normal unspecified
 53	        488 | 606 => 79,              // service or option not available
 54	        502 | 503 => 38,              // network out of order
 55	        500 | 580 => 41,              // temporary failure
 56	        504 => 34,                    // no circuit / channel available
 57	        500..=599 => 41,
 58	        _ => 16,
 59	    }
 60	}
 61	
 62	fn escape_reason_text(text: &str) -> String {
 63	    text.replace('\\', "\\\\").replace('"', "\\\"")
 64	}
 65	
 66	pub fn q850_reason_value(code: &rsip::StatusCode, detail: Option<&str>) -> String {
 67	    let fallback = format!("SIP {}", u16::from(code.clone()));
 68	    let text = detail
 69	        .map(|s| s.trim())
 70	        .filter(|s| !s.is_empty())
 71	        .map(|s| s.to_string())
 72	        .unwrap_or(fallback);
 73	    format!(
 74	        "Q.850;cause={};text=\"{}\"",
 75	        q850_cause_from_status(code),
 76	        escape_reason_text(&text)
 77	    )
 78	}
