 97	impl RouteInvite for DefaultRouteInvite {
 98	    async fn route_invite(
 99	        &self,
100	        option: InviteOption,
101	        origin: &rsip::Request,
102	        direction: &DialDirection,
103	        _cookie: &TransactionCookie,
104	    ) -> Result<RouteResult> {
105	        let (trunks_snapshot, routes_snapshot, source_trunk) =
106	            self.build_context(origin, direction).await;
107	        if matches!(direction, DialDirection::Inbound) {
108	            if let Some(source) = source_trunk.as_ref() {
109	                if let Some(trunk_cfg) = trunks_snapshot.get(&source.name) {
110	                    let from_user = extract_from_user(origin);
111	                    let to_user = extract_to_user(origin);
112	                    match trunk_cfg
113	                        .matches_incoming_user_prefixes(from_user.as_deref(), to_user.as_deref())
114	                    {
115	                        Ok(true) => {}
116	                        Ok(false) => {
117	                            let detail = format!(
118	                                "caller='{}', callee='{}' rejected by prefix policy",
119	                                from_user.as_deref().unwrap_or(""),
120	                                to_user.as_deref().unwrap_or("")
121	                            );
122	                            let reason =
123	                                q850_reason_value(&rsip::StatusCode::Forbidden, Some(&detail));
124	                            warn!(
125	                                trunk = %source.name,
126	                                from = from_user.as_deref().unwrap_or(""),
127	                                to = to_user.as_deref().unwrap_or(""),
128	                                reason = %reason,
129	                                "dropping inbound INVITE due to SIP trunk user prefix mismatch",
130	                            );
131	                            return Ok(RouteResult::Abort(
132	                                rsip::StatusCode::Forbidden,
133	                                Some(reason),
134	                            ));
135	                        }
136	                        Err(mismatch) => {
137	                            let reason = q850_reason_value(
138	                                &rsip::StatusCode::Forbidden,
139	                                Some(&mismatch.to_string()),
140	                            );
141	                            warn!(
142	                                trunk = %source.name,
143	                                from = from_user.as_deref().unwrap_or(""),
144	                                to = to_user.as_deref().unwrap_or(""),
145	                                reason = %reason,
146	                                "dropping inbound INVITE due to SIP trunk user prefix mismatch",
147	                            );
148	                            return Ok(RouteResult::Abort(
149	                                rsip::StatusCode::Forbidden,
150	                                Some(reason),
151	                            ));
152	                        }
153	                    }
154	                }
155	            }
156	        }
157	        let resource_lookup = self.data_context.as_ref() as &dyn RouteResourceLookup;
158	        match_invite(
159	            if trunks_snapshot.is_empty() {
160	                None
161	            } else {
162	                Some(&trunks_snapshot)
163	            },
164	            if routes_snapshot.is_empty() {
165	                None
166	            } else {
167	                Some(&routes_snapshot)
168	            },
169	            Some(resource_lookup),
170	            option,
171	            origin,
172	            source_trunk.as_ref(),
173	            self.routing_state.clone(),
174	            direction,
175	        )
176	        .await
177	    }
