233	        origin: &rsip::Request,
234	        direction: &DialDirection,
235	    ) -> Option<SourceTrunk> {
236	        if !matches!(direction, DialDirection::Inbound) {
237	            return None;
238	        }
239	
240	        if let Some(name) = self.source_trunk_hint.as_ref() {
241	            if let Some(config) = trunks.get(name) {
242	                return build_source_trunk(name.clone(), config, direction);
243	            }
244	        }
245	
246	        let via = origin.via_header().ok()?;
247	        let (_, target) = SipConnection::parse_target_from_via(via).ok()?;
248	        let ip: IpAddr = target.host.try_into().ok()?;
249	        let name = self.data_context.find_trunk_by_ip(&ip).await?;
250	        let config = trunks.get(&name)?;
251	        build_source_trunk(name, config, direction)
252	    }
253	}
