104	    async fn on_enter(
105	        &mut self,
106	        _controller: &mut CallController,
107	        context: &ApplicationContext,
108	    ) -> anyhow::Result<AppAction> {
109	        let call_id = context.call_info.session_id.clone();
110	
111	        self.send_event(RwiEvent::CallIncoming(
112	            crate::rwi::proto::CallIncomingData {
113	                call_id: call_id.clone(),
114	                context: self.context_name.clone(),
115	                caller: context.call_info.caller.clone(),
116	                callee: context.call_info.callee.clone(),
117	                direction: context.call_info.direction.clone(),
118	                trunk: None,
119	                sip_headers: std::collections::HashMap::new(),
120	            },
121	        ))
122	        .await;
123	
124	        if let Some(session_id) = &self.session_id {
125	            let claim_ok = {
126	                let mut gateway = self.gateway.write().await;
127	                gateway
128	                    .claim_call_ownership(session_id, call_id.clone(), OwnershipMode::Control)
129	                    .await
130	                    .is_ok()
131	            };
132	
133	            if claim_ok {
134	                self.owned = true;
135	                self.owned_call_id = Some(call_id.clone());
136	                self.send_event(RwiEvent::CallAnswered {
137	                    call_id: call_id.clone(),
138	                })
139	                .await;
140	            }
141	        }
142	
143	        Ok(AppAction::Continue)
144	    }
145	
146	    async fn on_dtmf(
147	        &mut self,
148	        digit: String,
149	        controller: &mut CallController,
150	        context: &ApplicationContext,
151	    ) -> anyhow::Result<AppAction> {
152	        if self.interrupt_on_dtmf {
153	            if let Some(track_id) = self.current_track_id.take() {
154	                controller.stop_audio().await.ok();
155	                self.interrupt_on_dtmf = false;
156	                self.send_event(RwiEvent::MediaPlayFinished {
157	                    call_id: context.call_info.session_id.clone(),
158	                    track_id,
159	                    interrupted: true,
160	                })
161	                .await;
162	            }
163	        }
164	
165	        self.send_event(RwiEvent::Dtmf {
166	            call_id: context.call_info.session_id.clone(),
167	            digit,
168	        })
169	        .await;
170	        Ok(AppAction::Continue)
171	    }
172	
173	    async fn on_audio_complete(
174	        &mut self,
175	        track_id: String,
176	        _controller: &mut CallController,
177	        context: &ApplicationContext,
178	    ) -> anyhow::Result<AppAction> {
179	        if self.current_track_id.as_deref() == Some(&track_id) {
180	            self.current_track_id = None;
181	            self.interrupt_on_dtmf = false;
182	        }
183	        self.send_event(RwiEvent::MediaPlayFinished {
184	            call_id: context.call_info.session_id.clone(),
185	            track_id,
186	            interrupted: false,
187	        })
188	        .await;
189	        Ok(AppAction::Continue)
190	    }
191	
192	    async fn on_external_event(
193	        &mut self,
194	        event: AppEvent,
195	        controller: &mut CallController,
196	        _context: &ApplicationContext,
197	    ) -> anyhow::Result<AppAction> {
198	        match event {
199	            AppEvent::Custom { ref name, ref data } if name == "media.play" => {
200	                let audio_file = data
201	                    .get("audio_file")
202	                    .and_then(|v| v.as_str())
203	                    .unwrap_or("")
204	                    .to_string();
205	                let track_id = data
206	                    .get("track_id")
207	                    .and_then(|v| v.as_str())
208	                    .unwrap_or("default")
209	                    .to_string();
210	                let interrupt_on_dtmf = data
211	                    .get("interrupt_on_dtmf")
212	                    .and_then(|v| v.as_bool())
213	                    .unwrap_or(false);
214	                let loop_playback = data.get("loop").and_then(|v| v.as_bool()).unwrap_or(false);
215	
216	                if !audio_file.is_empty() {
217	                    match controller
218	                        .play_audio_with_options(
219	                            &audio_file,
220	                            Some(track_id.clone()),
221	                            loop_playback,
222	                            interrupt_on_dtmf,
223	                        )
224	                        .await
225	                    {
226	                        Ok(_handle) => {
227	                            self.current_track_id = Some(track_id);
228	                            self.interrupt_on_dtmf = interrupt_on_dtmf;
229	                        }
230	                        Err(e) => {
231	                            tracing::warn!(
232	                                track_id = %track_id,
233	                                error = %e,
234	                                "RwiApp: media.play failed"
235	                            );
236	                        }
237	                    }
238	                }
239	            }
240	            AppEvent::Custom { name, data } => {
241	                tracing::debug!(event = %name, data = ?data, "RwiApp custom event");
242	            }
243	            _ => {}
244	        }
245	        Ok(AppAction::Continue)
246	    }
247	
248	    async fn on_timeout(
249	        &mut self,
250	        timeout_id: String,
251	        _controller: &mut CallController,
252	        _context: &ApplicationContext,
253	    ) -> anyhow::Result<AppAction> {
254	        tracing::debug!(timeout_id = %timeout_id, "RwiApp timeout");
255	        Ok(AppAction::Continue)
256	    }
257	
258	    async fn on_exit(&mut self, reason: ExitReason) -> anyhow::Result<()> {
259	        let _ = reason;
260	        if let (Some(session_id), Some(call_id)) = (&self.session_id, &self.owned_call_id) {
261	            let mut gateway = self.gateway.write().await;
262	            if self.owned {
263	                gateway.release_call_ownership(session_id, call_id).await;
264	            }
265	        }
266	        Ok(())
267	    }
268	}
