203	                        "%.1f" => Ok(format!("{:.1}", num)),
204	                        "%.2f" => Ok(format!("{:.2}", num)),
205	                        "%.3f" => Ok(format!("{:.3}", num)),
206	                        "%.4f" => Ok(format!("{:.4}", num)),
207	                        "%.5f" => Ok(format!("{:.5}", num)),
208	                        _ => Ok(format!("{}", num)),
209	                    }
210	                } else {
211	                    Ok(value.to_string())
212	                }
213	            },
214	        );
215	
216	        tmpl_env.add_filter(
217	            "json",
218	            |value: minijinja::Value| -> Result<String, minijinja::Error> {
219	                serde_json::to_string(&value).map_err(|e| {
220	                    minijinja::Error::new(
221	                        minijinja::ErrorKind::InvalidOperation,
222	                        format!("failed to serialize to json: {}", e),
223	                    )
224	                })
225	            },
226	        );
227	
228	        // ── t filter: {{ "nav.dashboard" | t }} ──────────────────────────
229	        let i18n_t = self.i18n.clone();
230	        let locale_t = locale.to_string();
231	        tmpl_env.add_filter("t", move |key: &str| -> String { i18n_t.t(&locale_t, key) });
232	
233	        // ── tvars filter: {{ "messages.saved" | tvars({"name": ext.name}) }} ─
234	        let i18n_tv = self.i18n.clone();
235	        let locale_tv = locale.to_string();
236	        tmpl_env.add_filter(
237	            "tvars",
238	            move |key: &str, vars: minijinja::Value| -> Result<String, minijinja::Error> {
239	                let vars_map: std::collections::HashMap<String, String> = if let Ok(obj) =
240	                    serde_json::from_str::<serde_json::Value>(
241	                        &serde_json::to_string(&vars).unwrap_or_default(),
242	                    ) {
243	                    if let serde_json::Value::Object(m) = obj {
244	                        m.into_iter()
245	                            .filter_map(|(k, v)| v.as_str().map(|s| (k, s.to_string())))
246	                            .collect()
247	                    } else {
248	                        Default::default()
249	                    }
250	                } else {
251	                    Default::default()
252	                };
253	                Ok(i18n_tv.t_with_vars(&locale_tv, key, &vars_map))
254	            },
255	        );
256	
257	        let base_path_for_fn = self.base_path().to_string();
258	        tmpl_env.add_function(
259	            "url_for",
260	            move |suffix: &str| -> Result<String, minijinja::Error> {
261	                let trimmed = suffix.trim();
262	                if trimmed.is_empty() || trimmed == "/" {
263	                    return Ok(format!("{}/", base_path_for_fn));
264	                }
265	                if trimmed.starts_with('/') {
266	                    if base_path_for_fn == "/" {
267	                        Ok(trimmed.to_string())
268	                    } else {
269	                        Ok(format!("{}{}", base_path_for_fn, trimmed))
270	                    }
271	                } else if base_path_for_fn == "/" {
272	                    Ok(format!("/{}", trimmed))
273	                } else {
274	                    Ok(format!("{}/{}", base_path_for_fn, trimmed))
275	                }
276	            },
277	        );
278	
279	        let mut paths = vec!["templates".to_string()];
280	        if let Some(app_state) = self.app_state() {
281	            paths.extend(
282	                app_state
283	                    .addon_registry
284	                    .get_template_dirs(app_state.clone()),
285	            );
286	        }
287	
288	        tmpl_env.set_loader(move |name| {
289	            for base in &paths {
290	                let path = std::path::Path::new(base).join(name);
291	                if path.exists() {
292	                    return std::fs::read_to_string(path).map(Some).map_err(|_| {
293	                        minijinja::Error::new(
294	                            minijinja::ErrorKind::TemplateNotFound,
295	                            "failed to load template",
296	                        )
297	                    });
298	                }
299	            }
300	            Ok(None)
301	        });
302	
303	        RenderTemplate {
304	            tmpl_env: &tmpl_env,
305	            template_name: template,
306	            context: &ctx,
307	        }
308	        .into_response()
309	    }
