 53	    /// Create a new RWI session and return the Arc handle.
 54	    /// The caller must call [`set_session_event_sender`] with the WS sender after this.
 55	    pub fn create_session(&mut self, identity: RwiIdentity) -> Arc<RwLock<RwiSession>> {
 56	        let (command_tx, _command_rx) = tokio::sync::mpsc::unbounded_channel();
 57	        let session = RwiSession::new(identity, command_tx);
 58	        let session_id = session.id.clone();
 59	        let session = Arc::new(RwLock::new(session));
 60	        self.sessions.insert(session_id.clone(), session.clone());
 61	        session
 62	    }
 63	
 64	    /// Register the WebSocket event sender for a session so that `send_event`
 65	    /// and `fan_out_event_to_context` can deliver events to it.
 66	    pub fn set_session_event_sender(&mut self, session_id: &SessionId, sender: WsEventSender) {
 67	        self.session_event_senders
 68	            .insert(session_id.clone(), sender);
 69	    }
 70	
 71	    pub async fn remove_session(&mut self, session_id: &SessionId) {
 72	        self.session_event_senders.remove(session_id);
 73	        if let Some(session) = self.sessions.remove(session_id) {
 74	            let session = session.read().await;
 75	            for ctx in &session.subscribed_contexts {
 76	                if let Some(subs) = self.context_subscriptions.get_mut(ctx) {
 77	                    subs.remove(session_id);
 78	                }
 79	            }
 80	            for call_id in session.owned_calls.keys() {
 81	                self.call_ownership.remove(call_id);
 82	            }
 83	            for call_id in session.supervisor_targets.keys() {
 84	                self.supervisor_calls.remove(call_id);
 85	            }
 86	        }
 87	    }
 88	
 89	    pub async fn subscribe(&mut self, session_id: &SessionId, contexts: Vec<Context>) -> bool {
 90	        if let Some(session) = self.sessions.get(session_id) {
 91	            let mut session = session.write().await;
 92	            session.subscribe(contexts.clone());
 93	            for ctx in contexts {
 94	                self.context_subscriptions
 95	                    .entry(ctx)
 96	                    .or_insert_with(HashSet::new)
 97	                    .insert(session_id.clone());
 98	            }
 99	            true
100	        } else {
101	            false
102	        }
103	    }
104	
105	    pub async fn unsubscribe(&mut self, session_id: &SessionId, contexts: &[Context]) -> bool {
106	        if let Some(session) = self.sessions.get(session_id) {
107	            let mut session = session.write().await;
108	            session.unsubscribe(contexts);
109	            for ctx in contexts {
110	                if let Some(subs) = self.context_subscriptions.get_mut(ctx) {
111	                    subs.remove(session_id);
112	                }
113	            }
114	            true
115	        } else {
116	            false
117	        }
118	    }
119	
120	    pub async fn claim_call_ownership(
121	        &mut self,
122	        session_id: &SessionId,
123	        call_id: CallId,
124	        mode: OwnershipMode,
125	    ) -> Result<(), ClaimError> {
126	        if let Some(current_owner) = self.call_ownership.get(&call_id) {
127	            if current_owner != session_id {
128	                return Err(ClaimError::AlreadyOwned);
129	            }
130	        }
131	
132	        if let Some(session) = self.sessions.get(session_id) {
133	            let mut session = session.write().await;
134	            if session.claim_call(call_id.clone(), mode) {
135	                self.call_ownership.insert(call_id, session_id.clone());
136	                return Ok(());
137	            }
138	            Err(ClaimError::AlreadyOwned)
139	        } else {
140	            Err(ClaimError::SessionNotFound)
141	        }
142	    }
143	
144	    pub async fn release_call_ownership(
145	        &mut self,
146	        session_id: &SessionId,
147	        call_id: &CallId,
148	    ) -> bool {
149	        if let Some(current_owner) = self.call_ownership.get(call_id) {
150	            if current_owner != session_id {
151	                return false;
152	            }
153	        }
154	
155	        if let Some(session) = self.sessions.get(session_id) {
156	            let mut session = session.write().await;
157	            if session.release_call(call_id) {
158	                self.call_ownership.remove(call_id);
159	                return true;
160	            }
161	        }
162	        false
163	    }
