237	    /// Send an event to the owner of a call_id (if any).
238	    pub fn send_event_to_call_owner(&self, call_id: &CallId, event: &RwiEvent) {
239	        if let Some(owner_id) = self.call_ownership.get(call_id) {
240	            self.send_event_to_session(owner_id, event);
241	        }
242	    }
