 21	pub async fn rwi_ws_handler(
 22	    _client_addr: ClientAddr,
 23	    ws: WebSocketUpgrade,
 24	    Query(params): Query<std::collections::HashMap<String, String>>,
 25	    Extension(auth): Extension<Arc<RwLock<RwiAuth>>>,
 26	    Extension(gateway): Extension<Arc<RwLock<RwiGateway>>>,
 27	    Extension(call_registry): Extension<Arc<ActiveProxyCallRegistry>>,
 28	    Extension(sip_server): Extension<Option<SipServerRef>>,
 29	    headers: HeaderMap,
 30	) -> impl IntoResponse {
 31	    let token = extract_token(&headers, &params);
 32	
 33	    let identity = match token {
 34	        Some(t) => {
 35	            let auth = auth.read().await;
 36	            auth.validate_token(&t)
 37	        }
 38	        None => None,
 39	    };
 40	
 41	    let identity = match identity {
 42	        Some(i) => i,
 43	        None => {
 44	            return (
 45	                StatusCode::UNAUTHORIZED,
 46	                [(
 47	                    header::WWW_AUTHENTICATE,
 48	                    r#"Bearer realm="rwi", error="invalid_token""#,
 49	                )],
 50	            )
 51	                .into_response();
 52	        }
 53	    };
 54	
 55	    ws.protocols(["rwi-v1"])
 56	        .on_upgrade(async move |socket| {
 57	            handle_websocket(socket, identity, gateway, call_registry, sip_server).await;
 58	        })
 59	        .into_response()
 60	}
 61	
 62	fn extract_token(
 63	    headers: &HeaderMap,
 64	    query_params: &std::collections::HashMap<String, String>,
 65	) -> Option<String> {
 66	    if let Some(auth_header) = headers.get("authorization") {
 67	        if let Ok(auth_str) = auth_header.to_str() {
 68	            if auth_str.starts_with("Bearer ") {
 69	                return Some(auth_str[7..].to_string());
 70	            }
 71	        }
 72	    }
 73	
 74	    query_params.get("token").cloned()
 75	}
