 77	/// Single unified WebSocket session loop.
 78	///
 79	/// Architecture:
 80	/// ```text
 81	///   ws_receiver -> [recv_task]
 82	///                      | parse + process command
 83	///                      | build RwiResponse JSON
 84	///                      v
 85	///                  [ws_tx channel]  <- gateway event fan-out also writes here
 86	///                      |
 87	///                  [write_task] -> ws_sender
 88	/// ```
 89	async fn handle_websocket(
 90	    socket: WebSocket,
 91	    identity: RwiIdentity,
 92	    gateway: Arc<RwLock<RwiGateway>>,
 93	    call_registry: Arc<ActiveProxyCallRegistry>,
 94	    sip_server: Option<SipServerRef>,
 95	) {
 96	    let (mut ws_sender, mut ws_receiver) = socket.split();
 97	
 98	    let (ws_tx, mut ws_rx) = mpsc::unbounded_channel::<String>();
 99	
100	    let processor = {
101	        let p = RwiCommandProcessor::new(call_registry, gateway.clone());
102	        let p = if let Some(server) = sip_server {
103	            p.with_sip_server(server)
104	        } else {
105	            p
106	        };
107	        Arc::new(p)
108	    };
109	
110	    let session_id = {
111	        let mut gw = gateway.write().await;
112	        let session = gw.create_session(identity.clone());
113	        let id = session.read().await.id.clone();
114	        let (event_tx, mut event_rx) = mpsc::unbounded_channel::<serde_json::Value>();
115	        let ws_tx_clone = ws_tx.clone();
116	        tokio::spawn(async move {
117	            while let Some(v) = event_rx.recv().await {
118	                if let Ok(s) = serde_json::to_string(&v) {
119	                    let _ = ws_tx_clone.send(s);
120	                }
121	            }
122	        });
123	        gw.set_session_event_sender(&id, event_tx);
124	        id
125	    };
126	
127	    let write_task = tokio::spawn(async move {
128	        while let Some(msg) = ws_rx.recv().await {
129	            if ws_sender.send(Message::Text(msg.into())).await.is_err() {
130	                break;
131	            }
132	        }
133	    });
134	
135	    let (command_tx, _command_rx) = mpsc::unbounded_channel::<RwiCommandMessage>();
136	
137	    let session_id_clone = session_id.clone();
138	    let gateway_clone = gateway.clone();
139	    let ws_tx_resp = ws_tx.clone();
140	    let recv_task = tokio::spawn(async move {
141	        while let Some(msg) = ws_receiver.next().await {
142	            match msg {
143	                Ok(Message::Text(text)) => {
144	                    let text = text.to_string();
145	                    let response_json = handle_text_message(
146	                        &text,
147	                        &command_tx,
148	                        processor.clone(),
149	                        &session_id_clone,
150	                        gateway_clone.clone(),
151	                    )
152	                    .await;
153	                    if let Some(json) = response_json {
154	                        let _ = ws_tx_resp.send(json);
155	                    }
156	                }
157	                Ok(Message::Close(_)) => break,
158	                Err(_) => break,
159	                _ => {}
160	            }
161	        }
162	    });
163	
164	    tokio::select! {
165	        _ = write_task => {}
166	        _ = recv_task => {}
167	    }
168	
169	    let mut gw = gateway.write().await;
170	    gw.remove_session(&session_id).await;
171	}
172	
173	/// Process one text frame from the WebSocket.
174	///
175	/// Returns the JSON string to send back as a response (always — even for errors).
176	async fn handle_text_message(
177	    text: &str,
178	    command_tx: &mpsc::UnboundedSender<RwiCommandMessage>,
179	    processor: Arc<RwiCommandProcessor>,
180	    session_id: &str,
181	    gateway: Arc<RwLock<RwiGateway>>,
182	) -> Option<String> {
183	    let value: serde_json::Value = match serde_json::from_str(text) {
184	        Ok(v) => v,
185	        Err(e) => {
186	            return error_response("", "parse_error", e.to_string());
187	        }
188	    };
189	
190	    let action = match value.get("action").and_then(|v| v.as_str()) {
191	        Some(a) => a.to_string(),
192	        None => {
193	            return error_response("", "missing_action", "action field required");
194	        }
195	    };
196	
197	    let action_id = value
198	        .get("action_id")
199	        .and_then(|v| v.as_str())
200	        .map(String::from)
201	        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
202	
203	    let params = value.get("params").unwrap_or(&serde_json::Value::Null);
204	
205	    let command = match parse_action(&action, params) {
206	        Ok(cmd) => cmd,
207	        Err(msg) => {
208	            return error_response(&action_id, "unknown_action", msg);
209	        }
210	    };
211	
212	    match &command {
213	        RwiCommandPayload::Subscribe { contexts } => {
214	            let mut gw = gateway.write().await;
215	            gw.subscribe(&session_id.to_string(), contexts.clone())
216	                .await;
217	        }
218	        RwiCommandPayload::Unsubscribe { contexts } => {
219	            let mut gw = gateway.write().await;
220	            gw.unsubscribe(&session_id.to_string(), contexts).await;
221	        }
222	        RwiCommandPayload::DetachCall { call_id } => {
223	            let mut gw = gateway.write().await;
224	            if gw
225	                .release_call_ownership(&session_id.to_string(), call_id)
226	                .await
227	            {
228	                gw.detach_supervisor(&session_id.to_string(), call_id).await;
229	            }
230	        }
231	        _ => {}
232	    }
233	
234	    let call_id = extract_call_id(&command);
235	
236	    let result = processor.process_command(command).await;
237	
238	    let _ = command_tx.send(RwiCommandMessage {
239	        id: action_id.clone(),
240	        call_id,
241	        command: RwiCommandPayload::ListCalls,
242	    });
243	
244	    let resp = match result {
245	        Ok(cmd_result) => {
246	            let data = match cmd_result {
247	                crate::rwi::processor::CommandResult::ListCalls(calls) => {
248	                    serde_json::to_value(calls).ok()
249	                }
250	                crate::rwi::processor::CommandResult::CallFound { call_id } => {
251	                    Some(serde_json::json!({ "call_id": call_id }))
252	                }
253	                crate::rwi::processor::CommandResult::Originated { call_id } => {
254	                    {
255	                        let mut gw = gateway.write().await;
256	                        let _ = gw
257	                            .claim_call_ownership(
258	                                &session_id.to_string(),
259	                                call_id.clone(),
260	                                OwnershipMode::Control,
261	                            )
262	                            .await;
263	                    }
264	                    Some(serde_json::json!({ "call_id": call_id }))
265	                }
266	                crate::rwi::processor::CommandResult::MediaPlay { track_id } => {
267	                    Some(serde_json::json!({ "track_id": track_id }))
268	                }
269	                crate::rwi::processor::CommandResult::TransferAttended {
270	                    original_call_id,
271	                    consultation_call_id,
272	                } => Some(serde_json::json!({
273	                    "original_call_id": original_call_id,
274	                    "consultation_call_id": consultation_call_id,
275	                })),
276	                crate::rwi::processor::CommandResult::ConferenceCreated { conf_id } => {
277	                    Some(serde_json::json!({ "conf_id": conf_id }))
278	                }
279	                crate::rwi::processor::CommandResult::ConferenceMemberAdded {
280	                    conf_id,
281	                    call_id,
282	                } => Some(serde_json::json!({ "conf_id": conf_id, "call_id": call_id })),
283	                crate::rwi::processor::CommandResult::ConferenceMemberRemoved {
284	                    conf_id,
285	                    call_id,
286	                } => Some(serde_json::json!({ "conf_id": conf_id, "call_id": call_id })),
287	                crate::rwi::processor::CommandResult::ConferenceMemberMuted {
288	                    conf_id,
289	                    call_id,
290	                } => Some(serde_json::json!({ "conf_id": conf_id, "call_id": call_id })),
291	                crate::rwi::processor::CommandResult::ConferenceMemberUnmuted {
292	                    conf_id,
293	                    call_id,
294	                } => Some(serde_json::json!({ "conf_id": conf_id, "call_id": call_id })),
295	                crate::rwi::processor::CommandResult::ConferenceDestroyed { conf_id } => {
296	                    Some(serde_json::json!({ "conf_id": conf_id }))
297	                }
298	                crate::rwi::processor::CommandResult::Success => None,
299	            };
300	            RwiResponse {
301	                action_id,
302	                response: ResponseStatus::Success,
303	                data,
304	                error: None,
305	            }
306	        }
307	        Err(e) => {
308	            let err_code = match &e {
309	                crate::rwi::processor::CommandError::CallNotFound(_) => "not_found",
310	                crate::rwi::processor::CommandError::CommandFailed(_) => "command_failed",
311	                crate::rwi::processor::CommandError::NotImplemented(_) => "not_implemented",
312	            };
313	            RwiResponse {
314	                action_id,
315	                response: ResponseStatus::Error,
316	                data: None,
317	                error: Some(RwiError::new(err_code, e.to_string())),
318	            }
319	        }
320	    };

