164	pub enum TransferEndpoint {
165	    Uri(String),
166	    Queue(String),
167	}
168	
169	impl TransferEndpoint {
170	    pub fn parse(value: &str) -> Option<Self> {
171	        let trimmed = value.trim();
172	        if trimmed.is_empty() {
173	            return None;
174	        }
175	
176	        const QUEUE_PREFIX: &str = "queue:";
177	
178	        if trimmed.len() >= QUEUE_PREFIX.len()
179	            && trimmed[..QUEUE_PREFIX.len()].eq_ignore_ascii_case(QUEUE_PREFIX)
180	        {
181	            let name = trimmed[QUEUE_PREFIX.len()..].trim();
182	            if name.is_empty() {
183	                return None;
184	            }
185	            // If name is numeric, it's likely an ID, but we store it as string in TransferEndpoint::Queue
186	            return Some(TransferEndpoint::Queue(name.to_string()));
187	        }
188	        Some(TransferEndpoint::Uri(trimmed.to_string()))
189	    }
190	}
