193	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
194	        match self {
195	            TransferEndpoint::Uri(uri) => write!(f, "{}", uri),
196	            TransferEndpoint::Queue(name) => write!(f, "queue:{}", name),
197	        }
198	    }
199	}
