 47	    pub payload: Bytes,
 48	    pub orig_size: usize,
 49	    pub comp_size: usize,
 50	}
 51	
 52	pub fn process_packet(packet: Packet) -> ProcessedPacket {
 53	    let mut callid = None;
 54	    if matches!(packet.msg_type, MsgType::Sip) {
 55	        callid = extract_callid(&packet.payload);
 56	    }
 57	
 58	    let orig_size = packet.payload.len();
 59	    let (payload, comp_size, _compressed) = if orig_size >= 96 {
 60	        if let Ok(data) = zstd::encode_all(&packet.payload[..], 3) {
 61	            let size = data.len();
 62	            (data.into(), size, true)
 63	        } else {
 64	            (packet.payload, orig_size, false)
 65	        }
 66	    } else {
 67	        (packet.payload, orig_size, false)
 68	    };
 69	
 70	    ProcessedPacket {
 71	        msg_type: packet.msg_type,
 72	        callid,
 73	        src: format!("{}:{}", packet.src.0, packet.src.1),
 74	        dst: format!("{}:{}", packet.dst.0, packet.dst.1),
 75	        leg: None, // Will be set by caller for RTP packets
 76	        timestamp: packet.timestamp,
 77	        payload,
 78	        orig_size,
 79	        comp_size,
 80	    }
 81	}
