105	    pub async fn write_processed(&mut self, processed: ProcessedPacket) -> Result<()> {
106	        let dt = Local::now();
107	        let h = (dt.year(), dt.month(), dt.day(), dt.hour());
108	
109	        if self.db_conn.is_none() || self.current_hour != h {
110	            self.rotate(dt).await?;
111	            self.current_hour = h;
112	            self.call_id_cache.clear();
113	        }
114	
115	        let file = self.raw_file.as_mut().unwrap();
116	        let offset = file.metadata()?.len();
117	
118	        file.write_all(&0x5346u16.to_be_bytes())?; // Magic
119	        file.write_all(&(processed.orig_size as u32).to_be_bytes())?;
120	        file.write_all(&(processed.comp_size as u32).to_be_bytes())?;
121	        file.write_all(&processed.payload)?;
122	
123	        self.batch.push(Meta {
124	            msg_type: processed.msg_type,
125	            callid: processed.callid,
126	            src: processed.src,
127	            dst: processed.dst,
128	            leg: processed.leg,
129	            timestamp: processed.timestamp,
130	            offset,
131	            size: processed.comp_size,
132	        });
133	
134	        if self.batch.len() >= self.flush_count
135	            || self.last_flush.elapsed().as_secs() >= self.flush_interval
136	        {
137	            self.flush_batch().await?;
138	        }
139	
140	        Ok(())
141	    }
