155	    async fn rotate(&mut self, dt: DateTime<Local>) -> Result<()> {
156	        if !self.batch.is_empty() {
157	            self.flush_batch().await?;
158	        }
159	        let subdir = match self.subdirs {
160	            SipFlowSubdirs::Hourly => format!(
161	                "{:04}{:02}{:02}/{:02}",
162	                dt.year(),
163	                dt.month(),
164	                dt.day(),
165	                dt.hour()
166	            ),
167	            SipFlowSubdirs::Daily => format!("{:04}{:02}{:02}", dt.year(), dt.month(), dt.day()),
168	            SipFlowSubdirs::None => String::new(),
169	        };
170	        let dir = self.base_path.join(subdir);
171	        std::fs::create_dir_all(&dir)?;
172	
173	        let db_path = dir.join("sipflow.db");
174	        let raw_path = dir.join("data.raw");
175	
176	        let mut conn = SqliteConnectOptions::new()
177	            .filename(db_path)
178	            .create_if_missing(true)
179	            .connect()
180	            .await?;
181	
182	        // Create call_meta table for callid mapping
183	        sqlx::query(
184	            "CREATE TABLE IF NOT EXISTS call_meta (
185	                id INTEGER PRIMARY KEY AUTOINCREMENT,
186	                callid TEXT UNIQUE NOT NULL
187	            )",
188	        )
189	        .execute(&mut conn)
190	        .await?;
191	
192	        sqlx::query("CREATE INDEX IF NOT EXISTS idx_callid ON call_meta(callid)")
193	            .execute(&mut conn)
194	            .await?;
195	
196	        sqlx::query(
197	            "CREATE TABLE IF NOT EXISTS sip_msgs (
198	                id INTEGER PRIMARY KEY,
199	                call_id INTEGER NOT NULL,
200	                src TEXT NOT NULL,
201	                dst TEXT NOT NULL,
202	                timestamp INTEGER NOT NULL,
203	                offset INTEGER NOT NULL,
204	                size INTEGER NOT NULL
205	            )",
206	        )
207	        .execute(&mut conn)
208	        .await?;
209	
210	        sqlx::query("CREATE INDEX IF NOT EXISTS idx_sip_call ON sip_msgs(call_id)")
211	            .execute(&mut conn)
212	            .await?;
213	
214	        sqlx::query(
215	            "CREATE TABLE IF NOT EXISTS media_msgs (
216	                id INTEGER PRIMARY KEY,
217	                call_id INTEGER NOT NULL,
218	                leg INTEGER NOT NULL,
219	                src TEXT NOT NULL DEFAULT '',
220	                timestamp INTEGER NOT NULL,
221	                offset INTEGER NOT NULL,
222	                size INTEGER NOT NULL
223	            )",
224	        )
225	        .execute(&mut conn)
226	        .await?;
227	
228	        sqlx::query("CREATE INDEX IF NOT EXISTS idx_media_call ON media_msgs(call_id)")
229	            .execute(&mut conn)
230	            .await?;
231	
232	        let file = OpenOptions::new()
233	            .create(true)
234	            .append(true)
235	            .open(raw_path)?;
236	
237	        self.db_conn = Some(conn);
238	        self.raw_file = Some(file);
239	        Ok(())
240	    }
241	
242	    async fn flush_batch(&mut self) -> Result<()> {
243	        if self.batch.is_empty() {
244	            return Ok(());
245	        }
246	
247	        if let Some(conn) = self.db_conn.as_mut() {
248	            let mut tx = conn.begin().await?;
249	
250	            for meta in self.batch.drain(..) {
251	                // Get or create call_id from call_meta
252	                let call_id = if let Some(ref callid) = meta.callid {
253	                    // Check LRU cache first
254	                    if let Some(&cached_id) = self.call_id_cache.get(callid) {
255	                        cached_id
256	                    } else {
257	                        // Cache miss, query or insert into call_meta
258	                        let id: i32 = sqlx::query_scalar(
259	                            "INSERT INTO call_meta (callid) VALUES (?) 
260	                             ON CONFLICT(callid) DO UPDATE SET callid=callid 
261	                             RETURNING id",
262	                        )
263	                        .bind(callid)
264	                        .fetch_one(&mut *tx)
265	                        .await?;
266	
267	                        // Update LRU cache
268	                        self.call_id_cache.put(callid.clone(), id);
269	                        id
270	                    }
271	                } else {
272	                    continue; // Skip records without callid
273	                };
274	
275	                match meta.msg_type {
276	                    MsgType::Sip => {
277	                        sqlx::query(
278	                            "INSERT INTO sip_msgs (call_id, src, dst, timestamp, offset, size) VALUES (?, ?, ?, ?, ?, ?)",
279	                        )
280	                        .bind(call_id)
281	                        .bind(meta.src)
282	                        .bind(meta.dst)
283	                        .bind(meta.timestamp as i64)
284	                        .bind(meta.offset as i64)
285	                        .bind(meta.size as i64)
286	                        .execute(&mut *tx)
287	                        .await?;
288	                    }
289	                    MsgType::Rtp => {
290	                        let leg = meta.leg.unwrap_or(0);
291	                        sqlx::query(
292	                            "INSERT INTO media_msgs (call_id, leg, src, timestamp, offset, size) VALUES (?, ?, ?, ?, ?, ?)",
293	                        )
294	                        .bind(call_id)
295	                        .bind(leg)
296	                        .bind(meta.src)
297	                        .bind(meta.timestamp as i64)
298	                        .bind(meta.offset as i64)
299	                        .bind(meta.size as i64)
300	                        .execute(&mut *tx)
301	                        .await?;
302	                    }
303	                }
304	            }
305	            tx.commit().await?;
306	        }
307	        if let Some(file) = self.raw_file.as_mut() {
308	            file.flush()?;
309	        }
310	        self.last_flush = std::time::Instant::now();
311	        Ok(())
312	    }
