132	    fn normalize_path(&self, path: &str) -> String {
133	        let path = path.trim_start_matches('/');
134	        if self.prefix.is_empty() {
135	            path.to_string()
136	        } else {
137	            format!("{}/{}", self.prefix.trim_end_matches('/'), path)
138	        }
139	    }
140	
141	    fn object_path(&self, path: &str) -> ObjectPath {
142	        ObjectPath::from(self.normalize_path(path))
143	    }
144	
145	    pub async fn write(&self, path: &str, bytes: Bytes) -> Result<()> {
146	        if self.is_local {
147	            if let Some(local_path) = self.local_path(path) {
148	                if let Some(parent) = local_path.parent() {
149	                    tokio::fs::create_dir_all(parent).await?;
150	                }
151	            }
152	        }
153	        let object_path = self.object_path(path);
154	        self.inner.put(&object_path, bytes.into()).await?;
155	        Ok(())
156	    }
157	
158	    pub async fn read(&self, path: &str) -> Result<Bytes> {
159	        let object_path = self.object_path(path);
160	        let result = self.inner.get(&object_path).await?;
161	        let bytes = result.bytes().await?;
162	        Ok(bytes)
163	    }
164	
165	    pub async fn delete(&self, path: &str) -> Result<()> {
166	        let object_path = self.object_path(path);
167	        self.inner.delete(&object_path).await?;
168	        Ok(())
169	    }
170	
171	    pub async fn list(&self, prefix: Option<&str>) -> Result<Vec<ObjectMeta>> {
172	        let prefix = prefix
173	            .map(|p| self.object_path(p))
174	            .unwrap_or_else(|| self.object_path(""));
175	        let mut stream = self.inner.list(Some(&prefix));
176	        let mut files = Vec::new();
177	        while let Some(item) = stream.next().await {
178	            let meta = item?;
179	            files.push(meta);
180	        }
181	        Ok(files)
182	    }
183	
184	    pub fn is_local(&self) -> bool {
185	        self.is_local
186	    }
187	
188	    pub fn local_path(&self, path: &str) -> Option<PathBuf> {
189	        if let Some(root) = &self.local_root {
190	            Some(root.join(path.trim_start_matches('/')))
191	        } else {
192	            None
193	        }
194	    }
195	
196	    // Helper to upload a local file to storage (move)
197	    pub async fn upload_file(&self, local_path: &PathBuf, remote_path: &str) -> Result<()> {
198	        if self.is_local {
199	            let dest = self.local_path(remote_path).unwrap();
200	            if let Some(parent) = dest.parent() {
201	                tokio::fs::create_dir_all(parent).await?;
202	            }
203	            // If src and dest are the same, do nothing
204	            if local_path != &dest {
205	                tokio::fs::rename(local_path, dest).await?;
206	            }
207	        } else {
208	            let data = tokio::fs::read(local_path).await?;
209	            self.write(remote_path, Bytes::from(data)).await?;
210	            tokio::fs::remove_file(local_path).await?;
211	        }
212	        Ok(())
213	    }
214	}
