66	pub async fn create_db(database_url: &str) -> Result<DatabaseConnection> {
67	    if database_url.starts_with("sqlite://") {
68	        prepare_sqlite_database(database_url).map_err(|e| {
69	            tracing::error!("failed to prepare SQLite database {database_url} {:?}", e);
70	            let msg = format!("failed to prepare SQLite database {database_url}: {e}");
71	            anyhow::anyhow!(msg)
72	        })?;
73	    }
74	
75	    let db = Database::connect(database_url)
76	        .await
77	        .map_err(|e: sea_orm::DbErr| {
78	            tracing::error!("failed to connect to database {:?}", e);
79	            let msg = format!("failed to connect to database {database_url}: {e}");
80	            anyhow::anyhow!(msg)
81	        })?;
82	
83	    migration::Migrator::up(&db, None).await.map_err(|e| {
84	        tracing::error!("failed to run database migrations on {:?}", e);
85	        let msg = format!("failed to run database migrations on {database_url}: {e}");
86	        anyhow::anyhow!(msg)
87	    })?;
88	    Ok(db)
89	}

