 50	fn codec_info_rtpmap(info: &negotiate::CodecInfo) -> String {
 51	    let codec_name = match info.codec {
 52	        CodecType::PCMU => "PCMU",
 53	        CodecType::PCMA => "PCMA",
 54	        CodecType::G722 => "G722",
 55	        CodecType::G729 => "G729",
 56	        #[cfg(feature = "opus")]
 57	        CodecType::Opus => "opus",
 58	        CodecType::TelephoneEvent => "telephone-event",
 59	    };
 60	
 61	    match info.channels {
 62	        0 | 1 => format!("{}/{}", codec_name, info.clock_rate),
 63	        channels => format!("{}/{}/{}", codec_name, info.clock_rate, channels),
 64	    }
 65	}
