 74	fn audio_frame_timing(codec: CodecType, rtp_clock_rate: u32) -> AudioFrameTiming {
 75	    let frame_ms = 20u32;
 76	    let pcm_sample_rate = codec.samplerate();
 77	
 78	    AudioFrameTiming {
 79	        pcm_sample_rate,
 80	        pcm_samples_per_frame: (pcm_sample_rate * frame_ms / 1000) as usize,
 81	        rtp_ticks_per_frame: rtp_clock_rate * frame_ms / 1000,
 82	    }
