 82	#[async_trait]
 83	impl CallRouter for HttpCallRouter {
 84	    async fn resolve(
 85	        &self,
 86	        original: &rsip::Request,
 87	        _route_invite: Box<dyn RouteInvite>,
 88	        caller: &SipUser,
 89	        cookie: &TransactionCookie,
 90	    ) -> Result<Dialplan, (anyhow::Error, Option<rsip::StatusCode>)> {
 91	        let direction = if cookie.get_extension::<TrunkContext>().is_some() {
 92	            DialDirection::Inbound
 93	        } else {
 94	            DialDirection::Internal
 95	        };
 96	
 97	        let call_id = original
 98	            .call_id_header()
 99	            .map(|h| h.value().to_string())
100	            .unwrap_or_default();
101	        let from = original
102	            .from_header()
103	            .map(|h| h.value().to_string())
104	            .unwrap_or_default();
105	        let to = original
106	            .to_header()
107	            .map(|h| h.value().to_string())
108	            .unwrap_or_default();
109	
110	        let mut headers = HashMap::new();
111	        for header in original.headers.iter() {
112	            let h_str = header.to_string();
113	            if let Some((name, value)) = h_str.split_once(':') {
114	                headers.insert(name.trim().to_string(), value.trim().to_string());
115	            }
116	        }
117	
118	        let body = String::from_utf8_lossy(&original.body).to_string();
119	        let source_addr = if let Ok(via) = original.via_header() {
120	            if let Ok((_, target)) = SipConnection::parse_target_from_via(via) {
121	                Some(target.to_string())
122	            } else {
123	                None
124	            }
125	        } else {
126	            None
127	        };
128	
129	        let payload = HttpRequestPayload {
130	            call_id: call_id.clone(),
131	            from,
132	            to,
133	            source_addr,
134	            direction: direction.to_string(),
135	            method: original.method.to_string(),
136	            uri: original.uri.to_string(),
137	            headers,
138	            body,
139	        };
140	
141	        let mut request = self.client.post(&self.config.url).json(&payload);
142	
143	        if let Some(config_headers) = &self.config.headers {
144	            for (k, v) in config_headers {
145	                request = request.header(k, v);
146	            }
147	        }
148	
149	        let start = Instant::now();
150	        let response = request.send().await.map_err(|e| {
151	            let elapsed = start.elapsed();
152	            warn!(
153	                %call_id,
154	                from = %payload.from,
155	                to = %payload.to,
156	                elapsed_ms = elapsed.as_millis(),
157	                "HTTP router request failed: {}",
158	                e
159	            );
160	            (
161	                anyhow!("HTTP router request failed: {}", e),
162	                Some(rsip::StatusCode::ServiceUnavailable),
163	            )
164	        })?;
165	
166	        let elapsed = start.elapsed();
167	        if !response.status().is_success() {
168	            if self.config.fallback_to_static {
169	                warn!(
170	                    %call_id,
171	                    from = %payload.from,
172	                    to = %payload.to,
173	                    elapsed_ms = elapsed.as_millis(),
174	                    status = %response.status(),
175	                    "HTTP router returned error, falling back to static"
176	                );
177	                return Err((anyhow!("HTTP router returned error"), None));
178	            }
179	            return Err((
180	                anyhow!("HTTP router returned error: {}", response.status()),
181	                Some(rsip::StatusCode::ServiceUnavailable),
182	            ));
183	        }
184	
185	        let result: HttpResponsePayload = response.json().await.map_err(|e| {
186	            (
187	                anyhow!("Failed to parse HTTP router response: {}", e),
188	                Some(rsip::StatusCode::ServerInternalError),
189	            )
190	        })?;
191	
192	        info!(
193	            %call_id,
194	            from = %payload.from,
195	            to = %payload.to,
196	            elapsed_ms = elapsed.as_millis(),
197	            action = ?result.action,
198	            "HTTP router resolved route"
199	        );
200	
201	        match result.action {
202	            HttpRouteAction::Spam => {
203	                cookie.mark_as_spam(SpamResult::Spam);
204	                return Err((
205	                    anyhow!(
206	                        result
207	                            .reason
208	                            .unwrap_or_else(|| "marked as spam by HTTP router".to_string())
209	                    ),
210	                    Some(rsip::StatusCode::Forbidden),
211	                ));
212	            }
213	            HttpRouteAction::Reject | HttpRouteAction::Abort => {
214	                let status = result
215	                    .status
216	                    .and_then(|s| rsip::StatusCode::try_from(s).ok())
217	                    .unwrap_or(rsip::StatusCode::Forbidden);
218	                return Err((
219	                    anyhow!(
220	                        result
221	                            .reason
222	                            .unwrap_or_else(|| "rejected by HTTP router".to_string())
223	                    ),
224	                    Some(status),
225	                ));
226	            }
227	            HttpRouteAction::NotHandled => {
228	                return Err((anyhow!("not handled by HTTP router"), None));
229	            }
230	            HttpRouteAction::Forward => {
231	                let mut locs = Vec::new();
232	                let custom_headers = result.headers.map(|h| {
233	                    h.iter()
234	                        .map(|(k, v)| rsip::Header::Other(k.clone(), v.clone()))
235	                        .collect::<Vec<_>>()
236	                });
237	
238	                if let Some(targets) = result.targets {
239	                    for target in targets {
240	                        if let Ok(uri) = rsip::Uri::try_from(target.clone()) {
241	                            locs.push(Location {
242	                                aor: uri,
243	                                headers: custom_headers.clone(),
244	                                ..Default::default()
245	                            });
246	                        }
247	                    }
248	                }
249	
250	                let strategy = match result.strategy {
251	                    Some(HttpRouteStrategy::Parallel) => DialStrategy::Parallel(locs),
252	                    _ => DialStrategy::Sequential(locs),
253	                };
254	
255	                let mut dialplan = Dialplan::new(call_id, original.clone(), direction);
256	
257	                if let Some(from) = caller.from.as_ref() {
258	                    dialplan = dialplan.with_caller(from.clone());
259	                }
260	
261	                dialplan = dialplan.with_targets(strategy);
262	
263	                if let Some(record) = result.record {
264	                    dialplan.recording.enabled = record;
265	                }
266	
267	                if let Some(mode) = result.media_proxy {
268	                    dialplan.media.proxy_mode = mode;
269	                }
270	
271	                if let Some(with_orig) = result.with_original_headers {
272	                    dialplan.with_original_headers = with_orig;
273	                }
274	
275	                if let Some(exts) = result.extensions {
276	                    dialplan = dialplan.with_extension(exts);
277	                }
278	
279	                if let Some(timeout) = result.timeout {
280	                    dialplan.call_timeout = Duration::from_secs(timeout as u64);
281	                }
282	
283	                Ok(dialplan)
284	            }
285	        }
286	    }
287	}

