 32	pub enum QueueState {
 33	    /// Initial state before `on_enter`.
 34	    Init,
 35	    /// Answering the call (if accept_immediately is true).
 36	    Answering,
 37	    /// Playing hold music while waiting for an agent.
 38	    PlayingHold { attempt: u32 },
 39	    /// Dialing agents (sequential or parallel).
 40	    DialingAgents { attempt: u32 },
 41	    /// Call connected to an agent.
 42	    Connected { agent_uri: String },
 43	    /// Executing fallback action.
 44	    ExecutingFallback,
 45	    /// Terminal state.
 46	    Done,
 47	}
