 69	    /// Create a new `QueueApp` from a [`QueuePlan`].
 70	    pub fn new(plan: QueuePlan) -> Self {
 71	        Self {
 72	            plan,
 73	            state: QueueState::Init,
 74	            hold_playback: None,
 75	            answered: false,
 76	            current_agent_idx: 0,
