 81	    /// Get the next action based on fallback configuration.
 82	    async fn execute_fallback(&mut self) -> anyhow::Result<AppAction> {
 83	        info!("Queue: executing fallback action");
 84	        self.state = QueueState::ExecutingFallback;
 85	
 86	        let action = match &self.plan.fallback {
 87	            Some(QueueFallbackAction::Failure(failure_action)) => {
 88	                self.get_fallback_action(failure_action)
 89	            }
 90	            Some(QueueFallbackAction::Redirect { target }) => {
 91	                info!(target = %target, "Queue: fallback redirect");
 92	                AppAction::Transfer(target.to_string())
 93	            }
 94	            Some(QueueFallbackAction::Queue { name }) => {
 95	                info!(queue = %name, "Queue: fallback to another queue");
 96	                // For now, transfer to queue reference
 97	                AppAction::Transfer(format!("queue:{}", name))
 98	            }
 99	            None => {
100	                // Default: hangup with service unavailable
101	                AppAction::Hangup {
102	                    reason: Some(CallRecordHangupReason::ServerUnavailable),
103	                    code: Some(480),
104	                }
105	            }
106	        };
107	        Ok(action)
108	    }
109	
110	    /// Get fallback action without executing it.
111	    fn get_fallback_action(&self, action: &FailureAction) -> AppAction {
112	        match action {
113	            FailureAction::Hangup { code, reason } => {
114	                info!(?code, ?reason, "Queue: hangup fallback");
115	                AppAction::Hangup {
116	                    reason: reason
117	                        .as_ref()
118	                        .map(|_| CallRecordHangupReason::ServerUnavailable),
119	                    code: code.as_ref().map(|c| c.code()),
120	                }
121	            }
122	            FailureAction::PlayThenHangup {
123	                audio_file: _,
124	                use_early_media: _,
125	                status_code,
126	                reason,
127	            } => {
128	                info!("Queue: play then hangup fallback");
129	                // For simplicity, just hangup (play could be added if needed)
130	                AppAction::Hangup {
131	                    reason: reason
132	                        .as_ref()
133	                        .map(|_| CallRecordHangupReason::ServerUnavailable),
134	                    code: Some(status_code.code()),
135	                }
136	            }
137	            FailureAction::Transfer(endpoint) => {
138	                info!(target = ?endpoint, "Queue: transfer fallback");
139	                // Transfer to the endpoint
140	                match endpoint {
141	                    crate::call::TransferEndpoint::Uri(uri) => {
142	                        AppAction::Transfer(uri.to_string())
143	                    }
144	                    crate::call::TransferEndpoint::Queue(queue_name) => {
145	                        AppAction::Transfer(format!("queue:{}", queue_name))
146	                    }
147	                }
148	            }
149	        }
150	    }
151	
152	    /// Start or restart hold music.
153	    async fn start_hold_music(&mut self, ctrl: &mut CallController) -> anyhow::Result<()> {
154	        if let Some(ref hold) = self.plan.hold {
155	            if let Some(ref audio_file) = hold.audio_file {
156	                debug!(file = %audio_file, "Queue: starting hold music");
157	                self.hold_playback = Some(ctrl.play_audio(audio_file, true).await?);
158	            }
159	        }
160	        Ok(())
161	    }
162	
163	    /// Stop hold music (placeholder - actual cleanup handled by controller).
164	    async fn _stop_hold_music(&mut self) {
165	        if self.hold_playback.take().is_some() {
166	            debug!("Queue: stopping hold music");
167	            // Playback handles are automatically cleaned up by the controller
168	        }
169	    }
170	
171	    /// Get agent locations from dial strategy.
172	    fn get_agents(&self) -> Vec<&Location> {
173	        match &self.plan.dial_strategy {
174	            Some(DialStrategy::Sequential(locations)) => locations.iter().collect(),
175	            Some(DialStrategy::Parallel(locations)) => locations.iter().collect(),
176	            None => Vec::new(),
177	        }
178	    }
179	
180	    /// Check if we should use parallel dialing.
181	    fn is_parallel(&self) -> bool {
182	        matches!(self.plan.dial_strategy, Some(DialStrategy::Parallel(_)))
183	    }
184	}
