187	impl CallApp for QueueApp {
188	    fn app_type(&self) -> CallAppType {
189	        CallAppType::Queue
190	    }
191	
192	    fn name(&self) -> &str {
193	        self.plan
194	            .label
195	            .as_deref()
196	            .unwrap_or("queue")
197	    }
