199	    async fn on_enter(
200	        &mut self,
201	        ctrl: &mut CallController,
202	        _ctx: &ApplicationContext,
203	    ) -> anyhow::Result<AppAction> {
204	        info!("Queue: entering queue application");
205	        self.state = QueueState::Answering;
206	
207	        // Check if we have agents configured
208	        let agents = self.get_agents();
209	        if agents.is_empty() {
210	            warn!("Queue: no agents configured, executing fallback");
211	            return self.execute_fallback().await;
212	        }
213	
214	        // Answer immediately if configured
215	        if self.plan.accept_immediately {
216	            info!("Queue: answering call immediately");
217	            ctrl.answer().await?;
218	            self.answered = true;
219	        }
220	
221	        // Start hold music if configured
222	        self.start_hold_music(ctrl).await?;
223	
224	        // Transition to dialing state
225	        self.state = QueueState::DialingAgents { attempt: 1 };
226	        self.dial_attempts = 1;
227	
228	        // Return Continue to proceed with dialing
229	        // The actual dialing is handled by the session layer
230	        Ok(AppAction::Continue)
231	    }
232	
233	    async fn on_audio_complete(
234	        &mut self,
235	        _track_id: String,
236	        ctrl: &mut CallController,
237	        _ctx: &ApplicationContext,
238	    ) -> anyhow::Result<AppAction> {
239	        debug!("Queue: audio playback completed");
240	
241	        // If we're in hold state, restart hold music (it loops)
242	        if let QueueState::PlayingHold { attempt: _ } = self.state {
243	            // Hold music loop - restart it
244	            self.start_hold_music(ctrl).await?;
245	        }
246	
247	        Ok(AppAction::Continue)
248	    }
249	
250	    async fn on_external_event(
251	        &mut self,
252	        event: super::AppEvent,
253	        _ctrl: &mut CallController,
254	        _ctx: &ApplicationContext,
255	    ) -> anyhow::Result<AppAction> {
256	        match event {
257	            super::AppEvent::Custom { name, data } => match name.as_str() {
258	                "agent_connected" => {
259	                    if let Some(agent_uri) = data.get("agent_uri").and_then(|v| v.as_str()) {
260	                        info!(agent = %agent_uri, "Queue: agent connected");
261	                        self._stop_hold_music().await;
262	                        self.state = QueueState::Connected {
263	                            agent_uri: agent_uri.to_string(),
264	                        };
265	                        // Transfer to the connected agent
266	                        return Ok(AppAction::Transfer(agent_uri.to_string()));
267	                    }
268	                    Ok(AppAction::Continue)
269	                }
270	                "agent_busy" | "agent_no_answer" => {
271	                    info!(event = %name, "Queue: agent unavailable, retrying");
272	                    // Increment agent index for sequential
273	                    if !self.is_parallel() {
274	                        self.current_agent_idx += 1;
275	                    }
276	                    self.dial_attempts += 1;
277	
278	                    // Check if we should retry or fallback
279	                    let agents = self.get_agents();
280	                    if self.current_agent_idx >= agents.len() {
281	                        // Tried all agents
282	                        return self.execute_fallback().await;
283	                    }
284	
285	                    // Continue with next agent
286	                    self.state = QueueState::DialingAgents {
287	                        attempt: self.dial_attempts,
288	                    };
289	                    Ok(AppAction::Continue)
290	                }
291	                "all_agents_busy" => {
292	                    warn!("Queue: all agents busy");
293	                    return self.execute_fallback().await;
294	                }
295	                _ => Ok(AppAction::Continue),
296	            },
297	            _ => Ok(AppAction::Continue),
298	        }
299	    }
300	
301	    async fn on_exit(&mut self, reason: super::ExitReason) -> anyhow::Result<()> {
302	        info!(?reason, "Queue: exiting queue application");
303	        // Note: hold music cleanup is handled by the controller when app exits
304	        self.state = QueueState::Done;
305	        Ok(())
306	    }
307	}
