 33	#[derive(Default)]
 34	struct RegistryState {
 35	    entries: HashMap<String, ActiveProxyCallEntry>,
 36	    handles: HashMap<String, SipSessionHandle>,
 37	    handles_by_dialog: HashMap<String, SipSessionHandle>,
 38	    // session_id -> all registered dialog_ids (multiple dialogs per session during failover)
 39	    dialog_by_session: HashMap<String, Vec<String>>,
 40	}
 41	
 42	pub struct ActiveProxyCallRegistry {
 43	    inner: Mutex<RegistryState>,
 44	}
 45	
 46	impl ActiveProxyCallRegistry {
 47	    pub fn new() -> Self {
 48	        Self {
 49	            inner: Mutex::new(RegistryState::default()),
 50	        }
 51	    }
 52	
 53	    pub fn upsert(&self, entry: ActiveProxyCallEntry, handle: SipSessionHandle) {
 54	        let mut guard = self.inner.lock().unwrap();
 55	        guard.entries.insert(entry.session_id.clone(), entry);
 56	        guard
 57	            .handles
 58	            .insert(handle.session_id().to_string(), handle);
 59	    }
 60	
 61	    pub fn register_dialog(&self, dialog_id: String, handle: SipSessionHandle) {
 62	        let mut guard = self.inner.lock().unwrap();
 63	        guard
 64	            .dialog_by_session
 65	            .entry(handle.session_id().to_string())
 66	            .or_default()
 67	            .push(dialog_id.clone());
 68	        guard.handles_by_dialog.insert(dialog_id, handle);
 69	    }
 70	
 71	    pub fn unregister_dialog(&self, dialog_id: &str) {
 72	        let mut guard = self.inner.lock().unwrap();
 73	        if let Some(handle) = guard.handles_by_dialog.remove(dialog_id) {
 74	            if let Some(dialogs) = guard.dialog_by_session.get_mut(handle.session_id()) {
 75	                dialogs.retain(|d| d != dialog_id);
 76	                if dialogs.is_empty() {
 77	                    guard.dialog_by_session.remove(handle.session_id());
 78	                }
 79	            }
 80	        }
 81	    }
 82	
 83	    pub fn get_handle_by_dialog(&self, dialog_id: &str) -> Option<SipSessionHandle> {
 84	        let guard = self.inner.lock().unwrap();
 85	        guard.handles_by_dialog.get(dialog_id).cloned()
 86	    }
 87	
 88	    pub fn update<F>(&self, session_id: &str, updater: F)
 89	    where
 90	        F: FnOnce(&mut ActiveProxyCallEntry),
 91	    {
 92	        if let Some(entry) = self.inner.lock().unwrap().entries.get_mut(session_id) {
 93	            updater(entry);
 94	        }
 95	    }
 96	
 97	    pub fn remove(&self, session_id: &str) {
 98	        let mut guard = self.inner.lock().unwrap();
 99	        guard.entries.remove(session_id);
100	        guard.handles.remove(session_id);
101	        // Remove all dialog handles registered for this session
102	        if let Some(dialog_ids) = guard.dialog_by_session.remove(session_id) {
103	            for dialog_id in dialog_ids {
104	                guard.handles_by_dialog.remove(&dialog_id);
105	            }
106	        }
107	    }
108	
109	    pub fn count(&self) -> usize {
110	        self.inner.lock().unwrap().entries.len()
111	    }
112	
113	    pub fn list_recent(&self, limit: usize) -> Vec<ActiveProxyCallEntry> {
114	        let mut entries: Vec<_> = self
115	            .inner
116	            .lock()
117	            .unwrap()
118	            .entries
119	            .values()
120	            .cloned()
121	            .collect();
122	        entries.sort_by(|a, b| b.started_at.cmp(&a.started_at));
123	        if entries.len() > limit {
124	            entries.truncate(limit);
125	        }
126	        entries
127	    }
128	
129	    pub fn get(&self, session_id: &str) -> Option<ActiveProxyCallEntry> {
130	        self.inner.lock().unwrap().entries.get(session_id).cloned()
131	    }
132	
133	    pub fn get_handle(&self, session_id: &str) -> Option<SipSessionHandle> {
134	        self.inner.lock().unwrap().handles.get(session_id).cloned()
135	    }
136	
137	    /// Get all active session IDs
138	    pub fn session_ids(&self) -> Vec<String> {
139	        self.inner.lock().unwrap().entries.keys().cloned().collect()
140	    }
141	
142	    /// Alias for count() for SessionRegistry compatibility
143	    pub fn len(&self) -> usize {
144	        self.count()
145	    }
146	
147	    /// Register a unified session handle
148	    /// This is used by SipSession to register itself
149	    pub fn register_handle(&self, session_id: String, handle: SipSessionHandle) {
150	        let entry = ActiveProxyCallEntry {
151	            session_id: session_id.clone(),
152	            caller: None,
153	            callee: None,
154	            direction: "inbound".to_string(),
155	            started_at: Utc::now(),
156	            answered_at: None,
157	            status: ActiveProxyCallStatus::Ringing,
158	        };
159	        self.upsert(entry, handle);
160	    }
161	
162	    #[cfg(test)]
163	    pub fn handles_by_dialog_count(&self) -> usize {
164	        self.inner.lock().unwrap().handles_by_dialog.len()
165	    }
166	
167	    #[cfg(test)]
168	    pub fn dialog_by_session_count(&self) -> usize {
169	        self.inner.lock().unwrap().dialog_by_session.len()
170	    }
171	
172	    /// Cleanup stale entries that have been inactive for longer than max_age
173	    /// Returns the number of entries removed
174	    pub fn cleanup_stale(&self, max_age: std::time::Duration) -> usize {
175	        let cutoff = Utc::now() - chrono::Duration::from_std(max_age).unwrap_or_else(|_| chrono::Duration::hours(1));
176	        let mut guard = self.inner.lock().unwrap();
177	        
178	        let stale_ids: Vec<String> = guard
179	            .entries
180	            .iter()
181	            .filter(|(_, entry)| {
182	                let last_activity = entry.answered_at.unwrap_or(entry.started_at);
183	                last_activity < cutoff
184	            })
185	            .map(|(id, _)| id.clone())
186	            .collect();
187	        
188	        let count = stale_ids.len();
189	        for id in stale_ids {
190	            guard.entries.remove(&id);
191	            guard.handles.remove(&id);
192	            if let Some(dialog_ids) = guard.dialog_by_session.remove(&id) {
193	                for dialog_id in dialog_ids {
194	                    guard.handles_by_dialog.remove(&dialog_id);
195	                }
196	            }
197	        }
198	        
199	        count
200	    }
201	}
