 72	impl AuthModule {
 73	    pub fn create(server: SipServerRef, _config: Arc<ProxyConfig>) -> Result<Box<dyn ProxyModule>> {
 74	        let module = AuthModule::new(server);
 75	        Ok(Box::new(module))
