 82	    pub async fn authenticate_request(
 83	        &self,
 84	        tx: &Transaction,
 85	    ) -> Result<Option<SipUser>, AuthError> {
 86	        let mut auth_inner: Option<(Authorization, &str)> = None;
 87	        for header in tx.original.headers.iter() {
 88	            match header {
 89	                Header::Authorization(h) => {
 90	                    auth_inner = h.typed().ok().map(|auth| (auth, h.value()));
 91	                    break;
 92	                }
 93	                Header::ProxyAuthorization(h) => {
 94	                    auth_inner = h.typed().ok().map(|auth| (auth.0, h.value()));
 95	                    break;
 96	                }
 97	                _ => {}
 98	            }
 99	        }
100	        let (auth_inner, raw_auth_header) = match auth_inner {
101	            Some(auth) => auth,
102	            None => {
103	                return Ok(None);
104	            }
105	        };
106	        let user = SipUser::try_from(tx).map_err(|e| AuthError::Other(e))?;
107	        // Check if user exists and is enabled
108	        match self
109	            .server
110	            .user_backend
111	            .get_user(&user.username, user.realm.as_deref(), Some(&tx.original))
112	            .await?
113	        {
114	            Some(mut stored_user) => {
115	                if !stored_user.enabled {
116	                    info!(username = user.username, realm = ?user.realm, "User is disabled");
117	                    return Ok(None);
118	                }
119	                if let Some(realm) = user.realm.as_ref() {
120	                    if !self.server.is_same_realm(realm).await {
121	                        info!(username = user.username, realm = ?user.realm, "User is not in the same realm");
122	                        return Ok(None);
123	                    }
124	                }
125	                stored_user.merge_with(&user);
126	                match self.verify_credentials(
127	                    &stored_user,
128	                    &tx.original.method,
129	                    &auth_inner,
130	                    raw_auth_header,
131	                ) {
132	                    true => Ok(Some(stored_user)),
133	                    false => Ok(None),
134	                }
135	            }
136	            None => {
137	                info!(username = user.username, realm = ?user.realm, "authenticate_request missing");
138	                Ok(None)
139	            }
140	        }
141	    }
