199	
200	    async fn on_transaction_begin(
201	        &self,
202	        _token: CancellationToken,
203	        tx: &mut Transaction,
204	        cookie: TransactionCookie,
205	    ) -> Result<ProxyAction> {
206	        // Only authenticate INVITE and REGISTER requests
207	        if tx.original.method != rsip::Method::Invite
208	            && tx.original.method != rsip::Method::Register
209	        {
210	            return Ok(ProxyAction::Continue);
211	        }
212	
213	        let tx_user = SipUser::try_from(&*tx)?;
214	        let source = tx_user
215	            .destination
216	            .as_ref()
217	            .map(|d| d.to_string())
218	            .unwrap_or_else(|| "unknown".to_string());
219	
220	        for backend in self.server.auth_backend.iter() {
221	            match backend.authenticate(&tx.original, &cookie).await {
222	                Ok(Some(mut user)) => {
223	                    user.merge_with(&tx_user);
224	                    cookie.set_user(user);
225	                    return Ok(ProxyAction::Continue);
226	                }
227	                Err(e) => {
228	                    if matches!(e, AuthError::SpamDetected) {
229	                        cookie.mark_as_spam(SpamResult::Spam);
230	                    }
231	                    info!(error=%e, key = %tx.key, %source, "auth_backend authenticate failed");
232	                }
233	                _ => {}
234	            }
235	        }
236	
237	        if cookie.is_spam() {
238	            return Ok(ProxyAction::Abort);
239	        }
