113	    /// Dispatch a command using the unified session path
114	    fn dispatch_unified_command(
115	        &self,
116	        call_id: &str,
117	        command: RwiCommandPayload,
118	    ) -> Option<Result<CommandResult, CommandError>> {
119	        use crate::call::runtime::dispatch_rwi_command;
120	
121	        match dispatch_rwi_command(&self.call_registry, Some(call_id), command) {
122	            Ok(result) => {
123	                if result.success {
124	                    Some(Ok(CommandResult::Success))
125	                } else {
126	                    let msg = result
127	                        .message
128	                        .unwrap_or_else(|| "command failed".to_string());
129	                    // If command is not supported by unified path, return None to fall through to legacy
130	                    if msg.contains("not supported") || msg.contains("not implemented") {
131	                        return None;
132	                    }
133	                    // Convert "not found" errors to CallNotFound for consistency with legacy path
134	                    if msg.to_lowercase().contains("not found") {
135	                        Some(Err(CommandError::CallNotFound(call_id.to_string())))
136	                    } else {
137	                        Some(Err(CommandError::CommandFailed(msg)))
138	                    }
139	                }
140	            }
141	            Err(e) => {
142	                let msg = e.to_string();
143	                if msg.to_lowercase().contains("not found") {
144	                    Some(Err(CommandError::CallNotFound(call_id.to_string())))
145	                } else {
146	                    Some(Err(CommandError::CommandFailed(msg)))
147	                }
148	            }
149	        }
150	    }
151	
152	    pub async fn process_command(
153	        &self,
154	        command: RwiCommandPayload,
155	    ) -> Result<CommandResult, CommandError> {
156	        // Special handling for Bridge command: check both legs exist before dispatch
157	        if let RwiCommandPayload::Bridge { leg_a, leg_b } = &command {
158	            // Verify both legs exist
159	            if self.call_registry.get_handle(leg_a).is_none() {
160	                return Err(CommandError::CallNotFound(leg_a.clone()));
161	            }
162	            if self.call_registry.get_handle(leg_b).is_none() {
163	                return Err(CommandError::CallNotFound(leg_b.clone()));
164	            }
165	        }
166	
167	        // Special handling for Originate: it requires SIP server and should not go through unified dispatch
168	        if let RwiCommandPayload::Originate(req) = &command {
169	            return self.originate_call(req.clone()).await;
170	        }
171	
172	        // Special handling for queue commands that need extra logic beyond unified dispatch
173	        match &command {
174	            RwiCommandPayload::QueueEnqueue(req) => {
175	                return self.queue_enqueue(req.clone()).await;
176	            }
177	            RwiCommandPayload::QueueDequeue { call_id } => {
178	                return self.queue_dequeue(call_id).await;
179	            }
180	            RwiCommandPayload::QueueHold { call_id } => {
181	                return self.queue_hold(call_id).await;
182	            }
183	            RwiCommandPayload::QueueUnhold { call_id } => {
184	                return self.queue_unhold(call_id).await;
185	            }
186	            RwiCommandPayload::QueueSetPriority { call_id, priority } => {
187	                return self.queue_set_priority(call_id, *priority).await;
188	            }
189	            RwiCommandPayload::QueueAssignAgent { call_id, agent_id } => {
190	                return self.queue_assign_agent(call_id, agent_id).await;
191	            }
192	            RwiCommandPayload::QueueRequeue {
193	                call_id,
194	                queue_id,
195	                priority,
196	            } => {
197	                return self.queue_requeue(call_id, queue_id, *priority).await;
198	            }
199	            _ => {}
200	        }
201	
202	        // Special handling for record commands that need extra logic
203	        match &command {
204	            RwiCommandPayload::RecordStart(req) => {
205	                return self.record_start(req.clone()).await;
206	            }
207	            RwiCommandPayload::RecordPause { call_id } => {
208	                return self.record_pause(call_id).await;
209	            }
210	            RwiCommandPayload::RecordResume { call_id } => {
211	                return self.record_resume(call_id).await;
212	            }
213	            RwiCommandPayload::RecordStop { call_id } => {
214	                return self.record_stop(call_id).await;
215	            }
216	            _ => {}
217	        }
218	
219	        // Special handling for commands that need SipServer but should use processor methods
220	        match &command {
221	            RwiCommandPayload::SetRingbackSource {
222	                target_call_id,
223	                source_call_id,
224	            } => {
225	                return self
226	                    .set_ringback_source(target_call_id, source_call_id)
227	                    .await;
228	            }
229	            RwiCommandPayload::SupervisorStop {
230	                supervisor_call_id,
231	                target_call_id,
232	            } => {
233	                return self
234	                    .supervisor_stop(supervisor_call_id, target_call_id)
235	                    .await;
236	            }
237	            _ => {}
238	        }
239	
240	        // Try unified dispatch first for all commands
241	        if let Some(call_id) = self.extract_call_id(&command) {
242	            if let Some(result) = self.dispatch_unified_command(&call_id, command.clone()) {
243	                tracing::debug!(
244	                    call_id = %call_id,
245	                    "Command handled via unified session runtime"
246	                );
247	                // For Bridge and Unbridge commands, emit events to gateway
248	                // (these were previously emitted by bridge_calls/unbridge_call)
249	                match &command {
250	                    RwiCommandPayload::Bridge { leg_a, leg_b } => {
251	                        let gw = self.gateway.read().await;
252	                        let event = RwiEvent::CallBridged {
253	                            leg_a: leg_a.clone(),
254	                            leg_b: leg_b.clone(),
255	                        };
256	                        gw.send_event_to_call_owner(leg_a, &event);
257	                        gw.send_event_to_call_owner(leg_b, &event);
258	                    }
259	                    RwiCommandPayload::Unbridge { call_id } => {
260	                        let gw = self.gateway.read().await;
261	                        let event = RwiEvent::CallUnbridged {
262	                            call_id: call_id.clone(),
263	                        };
264	                        gw.send_event_to_call_owner(call_id, &event);
265	                    }
266	                    _ => {}
267	                }
268	                return result;
269	            }
270	        }
271	
272	        // Handle commands that don't need a call_id via unified path
273	        match &command {
274	            RwiCommandPayload::ListCalls => {
275	                let calls = self.list_calls().await;
